INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214070, "vo_wac_05214", 21, 0, "", "", 5214, "", "", "vo_wac_05214_001", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214071, 105311, 11, 1, 0, 1, 5214, 0, 0.5, "忘れるはずがないだろう！\nアユミは我がギルドの数少ない良心……\nいや、重要な存在なのだからな！\n盛大に祝福させてくれ！　おめでとう！", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214072, 0, 91, "", "", "", 5214, "", "", "", "");
