INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (14114071, 105611, 3, "", 0.2, "", 14114, "", "", "wac_birthday_talk_smile", 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (14114072, "vo_wac_14114", 21, 0, "", "", 14114, "", "", "vo_wac_14114_001", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (14114073, 105611, 11, 1, 0, 1, 14114, 0, 0.5, "はは、その目に封印された\n誰かさんも、うれし涙は出るんだね？\n手間暇かけて、ケーキを\n準備したかいがあったよ。", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (14114074, 0, 91, "", "", "", 14114, "", "", "", "");
