INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (18814080, "vo_wac_18814", 21, 0, "", "", 18814, "", "", "vo_wac_18814_002", 0);
