INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26214066, 103311, 3, "", 0.2, "", 26214, "", "", "wac_birthday_talk_smile", 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26214067, "vo_wac_26214", 21, 0, "", "", 26214, "", "", "vo_wac_26214_001", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26214068, 103311, 11, 1, 0, 1, 26214, 0, 0.5, "そうだべ！\n誕生日おめでとう、シオシオ！\nこのケーキはシオシオの好きな\n牧場特製の食材も使って作ったべや！", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26214069, 0, 91, "", "", "", 26214, "", "", "", "");
