INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26224071, 101011, 3, "", 0.2, "", 26224, "", "", "wac_birthday_talk_wish", 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26224072, "vo_wac_26224", 21, 0, "", "", 26224, "", "", "vo_wac_26224_002", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26224073, 101011, 11, 1, 0, 1, 26224, 0, 0.5, "そうどすえ♪\nみんなで踊りながら、お祝いしまひょ♪\nカスミはんのために、王子はんも\n準備を手伝ってくれたんよ♪", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (26224074, 26224073, 91, "", "", "", 26224, "", "", "", "");
