INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27814076, 105511, 3, "", 0.2, "", 27814, "", "", "wac_birthday_talk_smile", 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27814077, "vo_wac_27814", 21, 0, "", "", 27814, "", "", "vo_wac_27814_002", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27814078, 105511, 11, 1, 0, 1, 27814, 0, 0.5, "お、お誕生日\nおめでとうございます、クウカさん。\nせ、せっかく、ケーキを用意したので、\nみんなでこれを食べませんか……？", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27814079, 0, 91, "", "", "", 27814, "", "", "", "");
