INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27814087, "vo_wac_27814", 21, 0, "", "", 27814, "", "", "vo_wac_27814_004", 0);
