INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314062, "vo_wac_31314", 21, 0, "", "", 31314, "", "", "vo_wac_31314_001", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314063, 101511, 11, 1, 0, 1, 31314, 0, 0.5, "うん、おめでとう～♪\nみんなでケーキも用意したから、\n楽しくお祝いしましょうね～\nほら、アオイちゃんも。", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314064, 0, 91, "", "", "", 31314, "", "", "", "");
