INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314067, "vo_wac_31314", 21, 0, "", "", 31314, "", "", "vo_wac_31314_002", 0);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314068, 104011, 11, 1, 0, 1, 31314, 0, 0.5, "お、おお、おめでとうございます！\n私のようなぼっちが、陽の者である\nハツネさんの誕生日をお祝いするのは、\n恐れ多い感じではあるんですが！", 10);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314069, 0, 91, "", "", "", 31314, "", "", "", "");
