INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (34314090, "vo_wac_34314", 21, 0, "", "", 34314, "", "", "vo_wac_34314_004", 0);
